/* Microfix 3.8.35: project actions live inside Layers; optional thumbnails + Ctrl multi-select */
function layerThumbMarkup(obj){
  if(!state.ui?.layerPreviews)return "";
  const kind=String(obj?.type||"shape");
  if(kind==="image"&&obj?.src)return `<span class="layer-thumb layer-thumb-image"><img src="${esc(obj.src)}" alt=""></span>`;
  if(["text","brief","note","node","button"].includes(kind)){
    const sample=String(obj?.text||obj?.title||obj?.label||obj?.name||"Aa").trim().slice(0,2)||"Aa";
    return `<span class="layer-thumb layer-thumb-text">${esc(sample)}</span>`;
  }
  const fill=validColor(obj?.fill,"#8b5cf6"),stroke=validColor(obj?.stroke,"#8b5cf6");
  return `<span class="layer-thumb layer-thumb-${esc(kind)}" style="--layer-thumb-fill:${fill};--layer-thumb-stroke:${stroke}"></span>`;
}
(()=>{const panel=$("#layersPanel"),head=panel?.querySelector(".panel-head"),pop=$("#projectPopover"),titleBox=head?.querySelector(":scope > div");if(!panel||!head||!pop||!titleBox)return;
  if(!$("#layersProjectMenuToggle")){
    titleBox.classList.add("layers-project-titlebox");
    const toggle=document.createElement("button");toggle.id="layersProjectMenuToggle";toggle.type="button";toggle.className="layers-project-menu-toggle";toggle.title=state.language==="ru"?"Меню проекта":"Project menu";toggle.innerHTML='<svg aria-hidden="true"><use href="#i-arrow"/></svg>';titleBox.append(toggle);
    toggle.addEventListener("click",e=>{e.preventDefault();e.stopPropagation();pop.hidden=!pop.hidden});
    new MutationObserver(()=>toggle.classList.toggle("open",!pop.hidden)).observe(pop,{attributes:true,attributeFilter:["hidden"]});
  }
  if(pop.parentElement!==panel)head.insertAdjacentElement("afterend",pop);pop.classList.add("layers-project-accordion");pop.hidden=true;
  if(!$("#layerPreviewSetting",pop)){
    const divider=document.createElement("div");divider.className="layers-project-divider";
    const label=document.createElement("label");label.id="layerPreviewSetting";label.className="layers-preview-setting";label.innerHTML=`<span>${state.language==="ru"?"Мини-превью слоёв":"Layer thumbnails"}</span><input id="layerPreviewToggle" type="checkbox">`;
    pop.append(divider,label);
    const input=$("#layerPreviewToggle",pop);input.checked=!!state.ui.layerPreviews;input.addEventListener("change",()=>{state.ui.layerPreviews=input.checked;renderLayers();queuePersist()});
  }
})();

/* Microfix 3.8.35: Layers becomes the project/navigation home */
#projectMenu{display:none!important}
.layers-panel{top:82px!important}
@media(max-width:1020px){.layers-panel{top:82px!important}}
.layers-project-titlebox{position:relative;display:grid;grid-template-columns:minmax(0,1fr) 28px;grid-template-rows:auto auto;column-gap:6px;align-items:center;min-width:0}
.layers-project-titlebox>small{grid-column:1/3}
.layers-project-titlebox>strong{grid-column:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.layers-project-menu-toggle{grid-column:2;grid-row:2;width:28px;height:28px;border:0;border-radius:8px;background:transparent;color:var(--muted);display:grid;place-items:center}
.layers-project-menu-toggle:hover{background:var(--surface-2);color:var(--text)}
.layers-project-menu-toggle svg{width:13px;transform:rotate(90deg);transition:transform .16s ease}
.layers-project-menu-toggle.open svg{transform:rotate(-90deg)}
.layers-panel #projectPopover.layers-project-accordion{position:static!important;inset:auto!important;width:auto!important;margin:0 10px 4px;padding:6px;border:1px solid var(--line);border-radius:12px;background:var(--surface-2);box-shadow:none;backdrop-filter:none}
.layers-panel #projectPopover.layers-project-accordion[hidden]{display:none!important}
.layers-panel #projectPopover.layers-project-accordion>button{width:100%;min-height:34px;padding:0 10px;border:0;border-radius:8px;background:transparent;text-align:left;color:var(--text);font-size:11px}
.layers-panel #projectPopover.layers-project-accordion>button:hover{background:var(--surface)}
.layers-project-divider{height:1px;margin:5px 4px;background:var(--line)}
.layers-preview-setting{height:34px;padding:0 10px;display:flex;align-items:center;justify-content:space-between;gap:12px;color:var(--muted);font-size:10px;cursor:pointer}
.layers-preview-setting input{accent-color:var(--accent)}
.layer-thumb{width:30px;min-width:30px;height:26px;border:1px solid var(--line);border-radius:7px;background:var(--layer-thumb-fill,var(--surface-2));box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--layer-thumb-stroke,var(--line)) 35%,transparent);overflow:hidden;display:grid;place-items:center;color:var(--text);font-size:8px;font-weight:800}
.layer-thumb-image img{width:100%;height:100%;object-fit:cover;display:block}
.layer-thumb-text{background:var(--surface);color:var(--muted)}
.layer-thumb-code,.layer-thumb-browser{background:linear-gradient(135deg,#111827,#283244)}
.layer-thumb-vector,.layer-thumb-ink{background:linear-gradient(135deg,transparent 42%,var(--layer-thumb-stroke,#8b5cf6) 44% 56%,transparent 58%)}
.layer-row:has(.layer-thumb){min-height:44px}
